// Build assumptions
zibai char lvl=90/90 cons=0 talent=1,10,9;
zibai add set="notsu" count=4;
zibai add weapon="harbinger" refine=5 lvl=90/90;
zibai add stats def=1369 hp=4780 atk=422 er=0.168 em=61 cr=0.432 cd=1.407;

linnea char lvl=80/90 cons=0 talent=1,10,6;
linnea add set="aubadeofmorningstarandmoon" count=4;
linnea add weapon="stringless" refine=5 lvl=90/90;
linnea add stats def=1542 hp=4780 atk=346 er=0.408 em=147 cr=0.494 cd=0.428;

columbina char lvl=90/90 cons=0 talent=8,10,10;
columbina add weapon="prototypeamber" refine=5 lvl=90/90;
columbina add set="silkenmoonsserenade" count=4;
columbina add stats def=0 hp=18476 atk=466 er=0.473 em=112 cr=0.393 cd=0.1018;


illuga char lvl=80/90 cons=6 talent=1,8,10;
illuga add weapon="kitain" refine=5 lvl=90/90;
illuga add set="gd" count=2;
illuga add set="wt" count=2;
illuga add stats def=431 hp=5772 atk=497 er=0.473 em=634 cr=0.171 cd=0.264;

// Target and Energy assumptions
options swap_delay=12 iteration=1000;
target lvl=100 resist=0.1 radius=2 pos=0,2.4 hp=999999999; # standard ST target
energy every interval=480,720 amount=1; # standard Energy drops


fn try_zibai_burst() {
  if .zibai.burst.ready {
    zibai attack, burst;
  }
}
let skill_time = -1000000;

// Rotation assumptions
active linnea;
for let i=0; i<6; i=i+1 {
  linnea skill;
  
  columbina skill;
  if .columbina.burst.ready {
    columbina burst;
  } else {
    columbina attack:2;
  }
  illuga skill, burst;
  zibai skill;
  if .zibai.cons >= 1 {
    zibai skill;
  }
  try_zibai_burst();
  zibai attack:4, skill;
  try_zibai_burst();
  zibai attack:4, skill;
  try_zibai_burst();
  zibai attack:4, skill;
  try_zibai_burst();
  zibai attack:4;
  if i < 5 && !.columbina.burst.ready && .zibai.cons == 0 {
    zibai attack:2;
  }
  if !i && .zibai.cons > 0 {
    zibai attack;
  }
  zibai skill;  
  
}
